def solve(inp):
    from collections import Counter
    h,w=len(inp),len(inp[0])
    bg=Counter(x for r in inp for x in r).most_common(1)[0][0]
    rects=[]; seen=[[False]*w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if inp[r][c]!=bg and not seen[r][c]:
                c2=c
                while c2<w and inp[r][c2]==inp[r][c]: c2+=1
                rects.append(inp[r][c]); seen[r][c:c2]=[True]*(c2-c)
    # sort by color desc
    rects.sort(key=lambda k:-k)
    out=[[0]*6 for _ in range(3)]  # big enough
    i=0
    while rects and i<len(out)-1:
        out[i%2][i//2]=rects.pop(0); i+=1
    return out[:2][:3] if False else [list(r) for r in out][:2]

